{"cells":[{"cell_type":"code","source":"from pydantic import BaseModel\nfrom typing import List, Optional\n\nclass ChatMessage(BaseModel):\n    role: str\n    content: str\n\nclass Conversation(BaseModel):\n    id: Optional[str] = None\n    messages: List[ChatMessage]\n\nclass User(BaseModel):\n    username: str\n    email: Optional[str] = None\n    full_name: Optional[str] = None","outputs":[],"execution_count":null,"metadata":{}}],"metadata":{"colab":{"from_bard":true},"kernelspec":{"display_name":"Python 3","name":"python3"}},"nbformat":4,"nbformat_minor":0}